                        <Route path="*" element={<Navigate to="/veterinario/mascotas" replace />} />
                      </Routes>
                    </main>
                  </div>
                </div>
              </>
            </ProtectedRoute>
          } />

          {/* Admin routes */}
          <Route path="/admin/*" element={
            <ProtectedRoute roles={['ADMIN']}>
              <>
                <Navbar />
                <div className="container-fluid">
                  <div className="row">
                    <Sidebar />
                    <main className="col-md-9 ms-sm-auto col-lg-10 px-md-4">
                      <Routes>
