                        <option value="Otro">Otro</option>
                      </select>
                      {formErrors.especie && <div className="invalid-feedback">{formErrors.especie}</div>}
                    </div>
                  </div>
                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">Raza</label>
                      <input
                        type="text"
                        className="form-control"
                        name="raza"
