                    <Link to="/login" className="text-primary text-decoration-none">
                      Inicia sesión aquí
                    </Link>
                  </p>
                </div>

                <hr />

                <div className="alert alert-info mb-0">
                  <small>
                    <i className="bi bi-info-circle me-2"></i>
                    <strong>Requisitos de contraseña:</strong>
